import {esc} from './visuals.mjs';

const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7l-9-4Zm-4 9 3 3 5-6',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m9 4a4 4 0 0 1 4 4v2m-5-18a4 4 0 0 1 0 8',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',sites:'M3 21V9h7v12M10 21V3h11v18M1 21h22M14 7h3m-3 4h3m-3 4h3M6 13v1m0 3v1',report:'M14 2H4v20h16V8l-6-6Zm0 0v6h6M8 12h8M8 16h8',car:'M5 17H3v-7l2-6h14l2 6v7h-2M5 17v3m14-3v3M3 10h18M7 14h1m8 0h1M5 17h14',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM12 6v6l4 3',sos:'M12 3 2 21h20L12 3Zm0 6v5m0 3v1',play:'m8 4 13 8-13 8V4',book:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3V3Zm9 2v17'};
export function icon(name,cls=''){return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.shield}"/></svg>`;}
const areas=[['live','On-site','protection','shield',-90],['worker','Workers &','support','people',0],['layout','Site','layout','pin',90],['supervisor','Multi-site','supervision','sites',180]];
function point(radius,angle){const a=angle*Math.PI/180;return [240+radius*Math.cos(a),240+radius*Math.sin(a)];}
function wedge(angle){const a=point(220,angle-43),b=point(220,angle+43),c=point(108,angle+43),d=point(108,angle-43);return `M${a} A220 220 0 0 1 ${b} L${c} A108 108 0 0 0 ${d} Z`;}
function wheel(){return `<svg class="workspace-wheel" viewBox="0 0 480 480" role="group" aria-label="Choose a worker safety area">${areas.map(([id,l1,l2,ico,angle],i)=>{const [x,y]=point(163,angle);return `<a href="#safety/${id}" data-action="area-${id}" aria-label="${l1} ${l2}" class="wheel-sector ${i===0?'featured':''}"><path class="wheel-wedge" d="${wedge(angle)}"/><g transform="translate(${x-12} ${y-40})" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[ico]}"/></g><text x="${x}" y="${y+6}" text-anchor="middle">${l1}</text><text x="${x}" y="${y+26}" text-anchor="middle">${l2}</text></a>`;}).join('')}<circle cx="240" cy="240" r="94" fill="#132c40" stroke="#3b5263"/><g transform="translate(228 187)" fill="none" stroke="#f9cc42" stroke-width="1.6"><path d="${paths.shield}"/></g><text class="wheel-centre" x="240" y="240" text-anchor="middle">Worker safety</text><text class="wheel-caption" x="240" y="262" text-anchor="middle">Choose your workspace</text><text class="wheel-caption" x="240" y="282" text-anchor="middle">04 connected areas</text></svg>`;}
export function homePage(site){return `<div class="home-view"><section class="home-hero"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-line"></span>THE WORKER SAFETY DEMONSTRATOR</div><h1>See the alert.<br><span>Follow the response.</span></h1><p>From a changing worksite to the worker’s wrist.<br class="desktop-break"> Explore protection, support and the decisions that follow.</p><div class="hero-actions"><button class="btn primary" data-action="tour-start">${icon('play')}Start guided demo</button><button class="btn hero-secondary" data-action="area-live">Explore workspace</button></div><div class="hero-caption">3-minute walkthrough · Explore at your own pace</div><div class="hero-site">${icon('pin')}<span>${esc(site.name)}<small>Melbourne, Victoria · Demo worksite</small></span></div></div><div class="hero-wheel">${wheel()}<p>Select an area to enter your workspace</p></div></section><section class="scenario-section" aria-labelledby="scenario-title"><div class="section-heading"><div><span class="eyebrow">STRAIGHT TO THE ACTION</span><h2 id="scenario-title">Try a scenario</h2></div><p>One situation. A visible response.</p></div><div class="scenario-cards">${[['vehicle','car','01','Vehicle approach','Play the moving vehicle and watch the alert arrive.','Play scenario'],['sos','sos','02','Worker SOS','Send a simulated help request and follow the response.','Try worker SOS'],['long','clock','03','Extended duty','Show a work-duration reminder and arrange relief.','Try extended duty']].map(([id,ico,n,title,copy,label])=>`<button class="scenario-card" data-action="demo-${id}"><div class="scenario-card-top">${icon(ico)}<span>${n}</span></div><h3>${title}</h3><p>${copy}</p><span class="scenario-card-link">${label}</span></button>`).join('')}</div></section><section class="home-report"><div class="report-mark">${icon('report')}</div><div><span class="eyebrow">COMPLETE THE PICTURE</span><h2>Review the response.</h2><p>Follow the event history, actions and supporting evidence.</p></div><button class="btn" data-action="nav-report">Open report</button></section><p class="home-note">Demonstration environment · Safety events and devices are simulated. Official SCATS and Vicmap data provide road context. <a href="./operating-guide.html" target="_blank" rel="noopener">Operating guide</a></p></div>`;}
